INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('2a347d43-accb-516a-a066-494b4982b81c', 'e0030000-0000-4000-8000-000000000103', 'published', 'Stodoła 60', 'PL', 60, 40, 'Domek w formie stodoły na stalowej ramie: 40 m² podstawy i 20 m² antresoli, razem 60 m² powierzchni użytkowej. Na parterze jest część wypoczynkowa z aneksem kuchennym, łazienka i sypialnia, na piętrze druga sypialnia. Ściany i dach mają grubość 25 cm. Wizualizacje pokazują trzy warianty elewacji: drewnianą boazerię, blachę CORTEN i ciemną blachę na rąbek. Dom można wielokrotnie przenosić. Cena obejmuje instalację elektryczną i hydrauliczną wykonaną zgodnie z obowiązującymi normami, bez umeblowania i sprzętu. Układ pomieszczeń ustala klient.', 'pod-klucz', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'rekreacyjny-caloroczny', NULL, 2, 1, 2, NULL, 'Dach dwuspadowy', 'Stalowa rama nośna z wypełnieniem ścian w technologii szkieletowej: drewno konstrukcyjne C-24, izolacja do wyboru (piana PUR, wełna mineralna lub włókno drzewne), grubość ściany i dachu 25 cm. Podłoga: płyta OSB z panelem winylowym.', NULL, 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje. Elewację, izolację, wykończenie wnętrza i ogrzewanie wybiera się w opcjach dodatkowych.', 'EUR', NULL, NULL, false, '2026-10-26T10:55:03.412Z'::timestamptz, '2026-10-26T11:49:38.541Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Do wyboru: maty na podczerwień w podłodze, klimatyzacja grzewczo-chłodząca lub piec na pelet.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"id":"stodola-room-0","name":"Część wypoczynkowa z aneksem kuchennym, łazienka i sypialnia","areaM2":40,"floorLevel":"parter"},{"id":"stodola-room-1","name":"Sypialnia na antresoli","areaM2":20,"floorLevel":"pietro"}]'::jsonb, NULL, NULL, NULL, NULL, 'stodola-60', NULL, NULL, 'temporary') ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('06b1bfca-362f-5f5c-a7d2-b7804d139167', 'e0030000-0000-4000-8000-000000000103', 'published', 'Domek Podwójny 75', 'PL', 75, NULL, 'Domek na stalowej ramie złożony z dwóch modułów po 34 m², połączonych zadaszonym łącznikiem o powierzchni 7 m², z tarasem 15 m² (razem 90 m²). Jedna część to strefa wypoczynkowa z aneksem kuchennym i łazienką, druga to salon z sypialnią. Dom można wielokrotnie przenosić. Cena obejmuje instalację elektryczną i hydrauliczną wykonaną zgodnie z obowiązującymi normami, bez umeblowania i sprzętu. Układ pomieszczeń ustala klient.', 'pod-klucz', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'rekreacyjny-caloroczny', NULL, 1, 1, 1, NULL, 'Dach płaski', 'Stalowa rama nośna z wypełnieniem ścian w technologii szkieletowej: drewno konstrukcyjne C-24 o przekroju 200x60 mm, izolacja do wyboru (piana PUR, wełna mineralna lub włókno drzewne). Podłoga: płyta OSB z panelem winylowym.', NULL, 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje. Elewację, izolację, wykończenie wnętrza i ogrzewanie wybiera się w opcjach dodatkowych.', 'EUR', NULL, NULL, false, '2026-10-26T10:26:32.607Z'::timestamptz, '2026-10-26T11:49:37.860Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Do wyboru: maty na podczerwień w podłodze, klimatyzacja grzewczo-chłodząca lub piec na pelet.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"id":"domek-podwojny-room-0","name":"Moduł wypoczynkowy z aneksem kuchennym i łazienką","areaM2":34,"floorLevel":"parter"},{"id":"domek-podwojny-room-1","name":"Moduł z salonem i sypialnią","areaM2":34,"floorLevel":"parter"},{"id":"domek-podwojny-room-2","name":"Łącznik budynków","areaM2":7,"floorLevel":"parter"}]'::jsonb, NULL, NULL, NULL, NULL, 'domek-podwojny-75', NULL, NULL, 'temporary') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('c507ba43-f36d-4862-bda7-bc9652cf0227', '2a347d43-accb-516a-a066-494b4982b81c', 'en', 'Stodoła 60', 'A barn-style cabin on a steel frame: 40 m² footprint plus a 20 m² mezzanine, 60 m² of usable area in total. The ground floor has a leisure area with a kitchenette, a bathroom and a bedroom, and the upper floor a second bedroom. Walls and roof are 25 cm thick. The visualisations show three facade variants: timber cladding, CORTEN steel and dark standing-seam sheet metal. The house can be moved many times. The price includes electrical and plumbing installations made to current standards, without furniture and appliances. The client decides the room layout.', '2026-10-26T10:55:03.412Z'::timestamptz, '2026-10-26T11:49:39.631Z'::timestamptz, '[{"id":"stodola-room-0","name":"Leisure area with kitchenette, bathroom and bedroom"},{"id":"stodola-room-1","name":"Bedroom on the mezzanine"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Load-bearing steel frame with timber-frame walls: C-24 structural timber, insulation of choice (PUR foam, mineral wool or wood fibre), wall and roof thickness 25 cm. Floor: OSB board with vinyl panels.', 'Gable roof', 'The client decides the final room layout, and the producer is open to the client''s proposals. Facade, insulation, interior finish and heating are chosen in the additional options.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('02c8b1ae-03e0-4c9f-b21c-99e667564c6a', '2a347d43-accb-516a-a066-494b4982b81c', 'de', 'Stodoła 60', 'Ein Haus in Scheunenform auf Stahlrahmen: 40 m² Grundfläche plus 20 m² Galerie, insgesamt 60 m² Nutzfläche. Im Erdgeschoss befinden sich ein Aufenthaltsbereich mit Küchenzeile, ein Bad und ein Schlafzimmer, im Obergeschoss ein zweites Schlafzimmer. Wände und Dach sind 25 cm dick. Die Visualisierungen zeigen drei Fassadenvarianten: Holzverkleidung, CORTEN-Stahl und dunkles Stehfalzblech. Das Haus lässt sich mehrfach versetzen. Der Preis umfasst Elektro- und Sanitärinstallation nach geltenden Normen, ohne Möbel und Geräte. Die Raumaufteilung bestimmt der Kunde.', '2026-10-26T10:55:03.412Z'::timestamptz, '2026-10-26T11:49:39.631Z'::timestamptz, '[{"id":"stodola-room-0","name":"Aufenthaltsbereich mit Küchenzeile, Bad und Schlafzimmer"},{"id":"stodola-room-1","name":"Schlafzimmer auf der Galerie"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tragender Stahlrahmen mit Wänden in Holzrahmenbauweise: Konstruktionsholz C-24, Dämmung nach Wahl (PUR-Schaum, Mineralwolle oder Holzfaser), Wand- und Dachstärke 25 cm. Boden: OSB-Platte mit Vinylpaneelen.', 'Satteldach', 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen. Fassade, Dämmung, Innenausbau und Heizung werden in den Zusatzoptionen gewählt.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('e27dbcd8-0671-4764-91e3-34edf973d97a', '2a347d43-accb-516a-a066-494b4982b81c', 'nl', 'Stodoła 60', 'Een huisje in de vorm van een schuur op een stalen frame: 40 m² grondoppervlak plus 20 m² vide, samen 60 m² bruikbare oppervlakte. Op de begane grond bevinden zich een verblijfsruimte met keukenhoek, een badkamer en een slaapkamer, op de verdieping een tweede slaapkamer. Wanden en dak zijn 25 cm dik. De visualisaties tonen drie gevelvarianten: houten bekleding, CORTEN-staal en donkere liggende felsplaat. Het huis kan meerdere keren worden verplaatst. De prijs omvat de elektrische en sanitaire installatie volgens de geldende normen, zonder meubels en apparatuur. De klant bepaalt de indeling.', '2026-10-26T10:55:03.412Z'::timestamptz, '2026-10-26T11:49:39.631Z'::timestamptz, '[{"id":"stodola-room-0","name":"Verblijfsruimte met keukenhoek, badkamer en slaapkamer"},{"id":"stodola-room-1","name":"Slaapkamer op de vide"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Dragend stalen frame met houtskeletwanden: constructiehout C-24, isolatie naar keuze (PUR-schuim, minerale wol of houtvezel), wand- en dakdikte 25 cm. Vloer: OSB-plaat met vinylpanelen.', 'Zadeldak', 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen. Gevel, isolatie, interieurafwerking en verwarming kies je in de aanvullende opties.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('6cde52e8-dd05-472a-b7a0-29ca0662362b', '06b1bfca-362f-5f5c-a7d2-b7804d139167', 'en', 'Domek Podwójny 75', 'A cabin on a steel frame made of two 34 m² modules joined by a covered 7 m² connector, with a 15 m² terrace (90 m² in total). One part is a leisure area with a kitchenette and bathroom, the other a living room with a bedroom. The house can be moved many times. The price includes electrical and plumbing installations made to current standards, without furniture and appliances. The client decides the room layout.', '2026-10-26T10:26:32.607Z'::timestamptz, '2026-10-26T11:49:38.796Z'::timestamptz, '[{"id":"domek-podwojny-room-0","name":"Leisure module with kitchenette and bathroom"},{"id":"domek-podwojny-room-1","name":"Module with living room and bedroom"},{"id":"domek-podwojny-room-2","name":"Connector between the modules"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Load-bearing steel frame with timber-frame walls: C-24 structural timber, 200x60 mm section, insulation of choice (PUR foam, mineral wool or wood fibre). Floor: OSB board with vinyl panels.', 'Flat roof', 'The client decides the final room layout, and the producer is open to the client''s proposals. Facade, insulation, interior finish and heating are chosen in the additional options.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('a42f953b-5e90-4f25-9090-82427edc28d5', '06b1bfca-362f-5f5c-a7d2-b7804d139167', 'de', 'Domek Podwójny 75', 'Ein Haus auf Stahlrahmen aus zwei Modulen von je 34 m², verbunden durch einen überdachten Verbinder von 7 m², mit einer 15 m² großen Terrasse (insgesamt 90 m²). Ein Teil ist der Aufenthaltsbereich mit Küchenzeile und Bad, der andere ein Wohnzimmer mit Schlafzimmer. Das Haus lässt sich mehrfach versetzen. Der Preis umfasst Elektro- und Sanitärinstallation nach geltenden Normen, ohne Möbel und Geräte. Die Raumaufteilung bestimmt der Kunde.', '2026-10-26T10:26:32.607Z'::timestamptz, '2026-10-26T11:49:38.796Z'::timestamptz, '[{"id":"domek-podwojny-room-0","name":"Aufenthaltsmodul mit Küchenzeile und Bad"},{"id":"domek-podwojny-room-1","name":"Modul mit Wohnzimmer und Schlafzimmer"},{"id":"domek-podwojny-room-2","name":"Verbinder der Gebäude"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tragender Stahlrahmen mit Wänden in Holzrahmenbauweise: Konstruktionsholz C-24, Querschnitt 200x60 mm, Dämmung nach Wahl (PUR-Schaum, Mineralwolle oder Holzfaser). Boden: OSB-Platte mit Vinylpaneelen.', 'Flachdach', 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen. Fassade, Dämmung, Innenausbau und Heizung werden in den Zusatzoptionen gewählt.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('e1e6f5e8-26d5-4ed7-9d3e-41f5cd62fe2d', '06b1bfca-362f-5f5c-a7d2-b7804d139167', 'nl', 'Domek Podwójny 75', 'Een huisje op een stalen frame, opgebouwd uit twee modules van 34 m², verbonden door een overdekte verbinding van 7 m², met een terras van 15 m² (samen 90 m²). Het ene deel is een verblijfsruimte met keukenhoek en badkamer, het andere een woonkamer met slaapkamer. Het huis kan meerdere keren worden verplaatst. De prijs omvat de elektrische en sanitaire installatie volgens de geldende normen, zonder meubels en apparatuur. De klant bepaalt de indeling.', '2026-10-26T10:26:32.607Z'::timestamptz, '2026-10-26T11:49:38.796Z'::timestamptz, '[{"id":"domek-podwojny-room-0","name":"Verblijfsmodule met keukenhoek en badkamer"},{"id":"domek-podwojny-room-1","name":"Module met woonkamer en slaapkamer"},{"id":"domek-podwojny-room-2","name":"Verbinding tussen de modules"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Dragend stalen frame met houtskeletwanden: constructiehout C-24, doorsnede 200x60 mm, isolatie naar keuze (PUR-schuim, minerale wol of houtvezel). Vloer: OSB-plaat met vinylpanelen.', 'Plat dak', 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen. Gevel, isolatie, interieurafwerking en verwarming kies je in de aanvullende opties.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_country_eligibility" ("product_id", "country_code", "status", "reason", "created_at", "updated_at") VALUES ('06b1bfca-362f-5f5c-a7d2-b7804d139167', 'PL', 'conditional', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', '2026-10-26T10:26:32.607Z'::timestamptz, '2026-10-26T11:49:38.795Z'::timestamptz) ON CONFLICT DO NOTHING;
